description:
Work out what fits in a packet (lesson 1.01):

```cpp
std::size_t maxPayload(std::size_t mtu, bool ipv6, bool tcp, std::size_t tcpOptions);
std::size_t packetsNeeded(std::size_t bytes, std::size_t payload);
double efficiency(std::size_t dataBytes, bool ipv6, bool tcp);
```

- **maxPayload**: the IP header is 20 bytes (40 for IPv6); the transport header is 20 bytes plus `tcpOptions` for TCP, or 8 bytes for UDP (`tcpOptions` is then ignored). The result is `mtu` minus both headers, or 0 if they do not fit.
- **packetsNeeded** to carry `bytes` bytes when each packet carries at most `payload` (0 bytes need 0 packets; a `payload` of 0 means it cannot be done: return 0).
- **efficiency**: the share of one packet's bytes on an Ethernet wire that is your data: `data / (data + 18 + IP header + transport header)`, where 18 is the Ethernet header and checksum, with plain TCP (no options).

starter.solution.cpp:
#include <cstddef>

std::size_t maxPayload(std::size_t mtu, bool ipv6, bool tcp, std::size_t tcpOptions) { return mtu; }
std::size_t packetsNeeded(std::size_t bytes, std::size_t payload) { return 1; }
double efficiency(std::size_t dataBytes, bool ipv6, bool tcp) { return 1.0; }

solution.solution.cpp:
#include <cstddef>

static std::size_t headers(bool ipv6, bool tcp, std::size_t tcpOptions)
{
    return (ipv6 ? 40 : 20) + (tcp ? 20 + tcpOptions : 8);
}

std::size_t maxPayload(std::size_t mtu, bool ipv6, bool tcp, std::size_t tcpOptions)
{
    const std::size_t h{ headers(ipv6, tcp, tcpOptions) };
    return mtu > h ? mtu - h : 0;
}

std::size_t packetsNeeded(std::size_t bytes, std::size_t payload)
{
    if (payload == 0) return 0;
    return (bytes + payload - 1) / payload;
}

double efficiency(std::size_t dataBytes, bool ipv6, bool tcp)
{
    const double total{ static_cast<double>(dataBytes + 18 + headers(ipv6, tcp, 0)) };
    return static_cast<double>(dataBytes) / total;
}

unitTests:
TEST("what fits") {
    CHECK_EQ(maxPayload(1500, false, true, 0), 1460u);
    CHECK_EQ(maxPayload(1500, false, false, 0), 1472u);
    CHECK_EQ(maxPayload(1500, true, true, 12), 1428u);
    CHECK_EQ(maxPayload(1280, true, false, 99), 1232u);
    CHECK_EQ(maxPayload(40, false, true, 0), 0u);
    CHECK_EQ(maxPayload(30, false, true, 0), 0u);
}
TEST("how many packets") {
    CHECK_EQ(packetsNeeded(1460, 1460), 1u);
    CHECK_EQ(packetsNeeded(1461, 1460), 2u);
    CHECK_EQ(packetsNeeded(0, 1460), 0u);
    CHECK_EQ(packetsNeeded(1000000, 1460), 685u);
    CHECK_EQ(packetsNeeded(10, 0), 0u);
}
TEST("efficiency") {
    CHECK_NEAR(efficiency(1460, false, true), 1460.0 / 1518.0, 1e-9);
    CHECK_NEAR(efficiency(40, false, false), 40.0 / 86.0, 1e-9);
    CHECK(efficiency(40, true, true) < 0.4);
}

